// inviteView is an invite as the API shows it. It never carries the token or its hash.
type inviteView struct {
	ID         string      `json:"id"`
	OrgID      string      `json:"org_id"`
	Email      string      `json:"email"`
	Role       store.Role  `json:"role"`
	InvitedBy  string      `json:"invited_by"`
	CreatedAt  time.Time   `json:"created_at"`
	ExpiresAt  time.Time   `json:"expires_at"`
	AcceptedAt *time.Time  `json:"accepted_at,omitempty"`
	RevokedAt  *time.Time  `json:"revoked_at,omitempty"`
}

func inviteViewOf(inv store.Invite) inviteView {
	return inviteView{ID: inv.ID, OrgID: inv.OrgID, Email: inv.Email, Role: inv.Role, InvitedBy: inv.InvitedBy,
		CreatedAt: inv.CreatedAt, ExpiresAt: inv.ExpiresAt(), AcceptedAt: inv.AcceptedAt, RevokedAt: inv.RevokedAt}
}

func (s *Server) listInvites(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	items := []inviteView{}
	for _, inv := range s.store.PendingInvites(p.OrgID, s.clock.Now()) {
		items = append(items, inviteViewOf(inv))
	}
	writeJSON(w, http.StatusOK, list{Items: items})
}

