func TestInviteTokens(t *testing.T) {
	e := apitest.New(t)
	type invited struct {
		ID        string    `json:"id"`
		ExpiresAt time.Time `json:"expires_at"`
	}
	// invite creates an invite as Acme's owner and returns it with the token from the email sent to the address.
	invite := func(email, role string) (invited, string, *apitest.Response) {
		t.Helper()
		before := len(e.Mail.Messages())
		r := e.Do("POST", "/v1/invites", e.Acme.Key, map[string]string{"email": email, "role": role})
		if r.Code != http.StatusCreated {
			t.Fatalf("invite %s: %s", email, r)
		}
		var inv invited
		r.JSON(&inv)
		msgs := e.Mail.Messages()
		if len(msgs) != before+1 {
			t.Fatalf("invite %s sent %d emails", email, len(msgs)-before)
		}
		m := regexp.MustCompile(`token=([^\s]+)`).FindStringSubmatch(msgs[len(msgs)-1].Body)
		if m == nil {
			t.Fatalf("no link in %q", msgs[len(msgs)-1].Body)
		}
		token, _ := url.QueryUnescape(m[1])
		return inv, token, r
	}
	accept := func(token string) *apitest.Response {
		return e.Do("POST", "/v1/invites/accept", "", map[string]string{"token": token, "name": "Someone"})
	}
	expectError := func(r *apitest.Response, status int, code string) {
		t.Helper()
		if r.Code != status || !strings.Contains(string(r.Body), `"error":"`+code+`"`) {
			t.Fatalf("want %d %s: %s", status, code, r)
		}
	}

	// A token is 32 random bytes in unpadded base64url, and no API answer or snapshot shows it.
	first, token1, r := invite("Pat@People.example", "member")
	if len(token1) != 43 {
		t.Fatalf("token %q has %d characters", token1, len(token1))
	}
	if b, err := base64.RawURLEncoding.DecodeString(token1); err != nil || len(b) != 32 {
		t.Fatalf("token %q is not 32 bytes of unpadded base64url: %v", token1, err)
	}
	if strings.Contains(string(r.Body), token1) {
		t.Fatalf("the create response shows the token: %s", r)
	}
	if want := apitest.Start.Add(7 * 24 * time.Hour); !first.ExpiresAt.Equal(want) {
		t.Fatalf("expires_at = %s, want %s", first.ExpiresAt, want)
	}
	snapshot, _ := json.Marshal(e.Store.Export())
	if strings.Contains(string(snapshot), token1) {
		t.Fatal("a snapshot holds the token")
	}
	_, viewerKey := e.AddMember(e.Acme, "viewer@people.example", store.RoleViewer)
	r = e.Do("GET", "/v1/invites", viewerKey, nil)
	if r.Code != http.StatusOK || strings.Contains(string(r.Body), "token") || strings.Contains(string(r.Body), token1) {
		t.Fatalf("a viewer reads the invites: %s", r)
	}

	// Inviting the same address again, in any case, revokes the earlier invite: only the newest token works.
	_, token2, _ := invite("pat@people.example", "admin")
	expectError(accept(token1), http.StatusNotFound, "invite_not_found")
	e.MustDo(http.StatusCreated, "POST", "/v1/invites/accept", "", map[string]string{"token": token2, "name": "Pat"}, nil)
	expectError(accept(token2), http.StatusGone, "invite_used")

	// A revoked invite is not found.
	revoked, token3, _ := invite("revoked@people.example", "member")
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/invites/"+revoked.ID, e.Acme.Key, nil, nil)
	expectError(accept(token3), http.StatusNotFound, "invite_not_found")

	// An invite can be accepted up to exactly 7 days after it was created, and not after.
