	if !reflect.DeepEqual(s2.Export(), st) {
		t.Fatalf("round trip changed the state:\n%+v\n%+v", s2.Export(), st)
	}
	if got, ok := s2.APIKeyByToken(k.Token); !ok || got.ID != k.ID {
		t.Fatal("the key does not work after FromState")
